  const digest = createHash('sha256');
  let frames = 0, stepMs = 0;
  const observe = (h: number, f: number) => {
    const before = ex.get_last_frame_index(h);
    frames += Math.max(0, f - before);
    ex.get_state_map(h, f);
    if (verify) {
