      digest.update(new Uint8Array(ex.memory.buffer, ex.scratch_ptr(), 84 * 8));
      const count = ex.get_updates(h, f);
      digest.update(String(count));
      digest.update(new Uint8Array(ex.memory.buffer, ex.events_ptr(), count * 3 * 8));
