        const contacts = ex.get_contact_positions(h, f, f);
        assert(contacts >= 0);
        digest.update(String(contacts));
        digest.update(new Uint8Array(ex.memory.buffer, ex.contact_positions_ptr(), contacts * 3 * 8));
