      // A detached prefix must not retain pointers into its source grid.
      const detached = ex.detach_engine(root);
      ex.free_engine(root);
      root = detached;
      observe(root, 200);
    }
    ex.free_engine(root);
  }
  return {stepMs, frames, fingerprint: verify ? digest.digest('hex') : null};
}
