import {readFileSync,writeFileSync} from 'node:fs';
import {run,instance,workloads} from '/home/holo/line/tools/measure/engine_workload.ts';
const samples=[];
for (const arm of ['baseline','direction_reserved']) {
  const module=new WebAssembly.Module(readFileSync(`/tmp/engine-round4/${arm}.wasm`));
  for (const workload of workloads) {
    const ex=instance(module), before=ex.memory.buffer.byteLength;
    const {frames}=run(ex,workload);
    samples.push({arm,workload,frames,initialWasmBytes:before,finalWasmBytes:ex.memory.buffer.byteLength});
  }
}
writeFileSync('/tmp/engine-round4/reserved-memory.json',JSON.stringify({description:'WASM linear-memory high-water size after each complete workload in a fresh instance; not live allocations or process RSS.',samples},null,2)+'\n');
